class ShoppingCart:
    MAXIMUM_ITEM_QUANTITY = 1 ** 1000  # Symbolic constant to replace potential magic numbers if needed, but here we just define a reasonable max
    MINIMUM_ITEM_QUANTITY = 0

    def __init__(self):
        self._items = {}

    def add_item(self, item, price, quantity=1):
        if quantity <= 0:
            return
        if item in self._items:
            self._items[item]['quantity'] += quantity
        else:
            self._items[item] = {'price': price, 'quantity': quantity}

    def remove_item(self, item, quantity=1):
        if item in self._items:
            self._items[item]['quantity'] -= quantity
            if self._items[item]['quantity'] <= 0:
                del self._items[item]

    def view_items(self) -> dict:
        return self._items

    def total_price(self) -> float:
        return self._calculate_total_price()

    def _calculate_total_price(self) -> float:
        return sum(item['quantity'] * item['price'] for item in self._items.values())

    def get_item_price(self, item) -> float:
        if item in self._items:
            return self._items[item]['price']
        return 0.0

    def get_item_quantity(self, item) -> int:
        if item in self._items:
            return self._items[item]['quantity']
        return 0
